# M23 Build-Health — Benchmark Trend (auto-generated).
#
# The reviewer asked for a benchmark TREND, not just a baseline: CI should append
# each run to a history and render the trajectory (Decode 120ms -> 118 -> 116)
# so performance drift is visible at a glance.
#
# Input : a benchmark_report.json (results: [{name, value, unit, passed}]) — the
#         canonical output of `mviewer_bench --enforce --regression`.
# Output: benchmark/report/trend.json (rolling history, last N runs) and
#         benchmark/report/index.html (per-metric SVG sparklines + last value).
#
# Run in the nightly `publish-health` job after the quality run so every nightly
# builds on the previous trajectory.

[CmdletBinding()]
param(
    [string]$Repo = (Resolve-Path (Join-Path $PSScriptRoot '..')),
    [string]$BenchmarkJson = '',
    [string]$History = (Join-Path $Repo 'benchmark/report/trend.json'),
    [string]$OutHtml = (Join-Path $Repo 'benchmark/report/index.html'),
    [int]$Keep = 60
)

$ErrorActionPreference = 'Stop'

$commit = ((git -C $Repo rev-parse --short HEAD 2>$null) + '')
$date = Get-Date -Format 'yyyy-MM-dd'

# Locate the current run's report.
$bj = $BenchmarkJson
if (-not $bj -or -not (Test-Path $bj)) {
    $cand = Get-ChildItem -Path (Join-Path $Repo 'build_msvc') -Recurse -Filter benchmark_report.json -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($cand) { $bj = $cand.FullName }
}
if (-not $bj -or -not (Test-Path $bj)) {
    Write-Host "benchmark_trend: no benchmark_report.json found; skipping"
    exit 0
}

try { $b = Get-Content $bj -Raw -Encoding UTF8 | ConvertFrom-Json }
catch { Write-Host "benchmark_trend: invalid JSON in $bj"; exit 1 }

$metrics = [ordered]@{}
foreach ($r in $b.results) {
    $metrics[[string]$r.name] = [math]::Round([double]$r.value, 3)
}

$run = [ordered]@{ date = $date; commit = $commit; metrics = $metrics }

$hist = @()
if (Test-Path $History) {
    try { $hist = @(Get-Content $History -Raw -Encoding UTF8 | ConvertFrom-Json) } catch { $hist = @() }
}
$hist = @($hist) + $run
if ($hist.Count -gt $Keep) { $hist = $hist[($hist.Count - $Keep) .. ($hist.Count - 1)] }
$hist | ConvertTo-Json -Depth 6 | Set-Content -Path $History -Encoding UTF8

# ---- SVG sparkline ----------------------------------------------------------
function Sparkline($vals) {
    if ($vals.Count -lt 2) { return '<span title="need &gt;1 run">n/a</span>' }
    $min = ($vals | Measure-Object -Minimum).Minimum
    $max = ($vals | Measure-Object -Maximum).Maximum
    $w = 140; $h = 26
    $pts = @()
    for ($i = 0; $i -lt $vals.Count; $i++) {
        $x = [math]::Round($w * $i / ($vals.Count - 1), 1)
        $y = if ($max -eq $min) { $h / 2 } else { [math]::Round($h - ($vals[$i] - $min) / ($max - $min) * ($h - 2) - 1, 1) }
        $pts += "$x,$y"
    }
    return "<svg width='$w' height='$h' role='img'><polyline points='$($pts -join ' ')' fill='none' stroke='#007acc' stroke-width='1.5'/></svg>"
}

$metricNames = @($hist[0].metrics.Keys) | Sort-Object
$rows = ''
foreach ($mn in $metricNames) {
    $vals = [System.Collections.Generic.List[double]]::new()
    foreach ($r in $hist) {
        if ($r.metrics.PSObject.Properties[$mn]) { $vals.Add([double]$r.metrics.$mn) }
    }
    $last = if ($vals.Count) { $vals[-1] } else { 0 }
    $rows += "    <tr><td><code>$mn</code></td><td>$last</td><td>$(Sparkline $vals)</td></tr>`n"
}

$html = @"
<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><title>MViewer Benchmark Trend</title>
<style>body{font-family:system-ui,Arial;margin:2rem}table{border-collapse:collapse}td,th{border:1px solid #ddd;padding:4px 10px;text-align:left}</style>
</head>
<body>
<h1>MViewer — Benchmark Trend</h1>
<p>Auto-generated by <code>scripts/benchmark_trend.ps1</code>. Last run: <b>$date</b> (commit <code>$commit</code>). Keeping last $Keep runs. Lower is better for latency metrics.</p>
<table>
  <tr><th>Scenario</th><th>Last value</th><th>Trend (old &#8594; new)</th></tr>
$rows</table>
<p>Baseline + &plusmn;10% regression gate: see <code>benchmark/performance_budget.json</code> and the nightly <code>quality</code> job.</p>
</body>
</html>
"@
Set-Content -Path $OutHtml -Value $html -Encoding UTF8
Write-Host "benchmark_trend: appended run; history now $($hist.Count) runs -> $OutHtml"
